<?php $isEdit=!empty($page);$val=function($key,$default='')use($page){return $page && isset($page->$key)?$page->$key:$default;}; ?>
<div class="container-fluid py-3"><div class="d-flex justify-content-between align-items-center"><h1><?=$isEdit?'Edit Page':'Add Page'?></h1><a class="btn btn-outline-secondary" href="<?=base_url('cms/pages')?>">Back to Pages</a></div>
 <?php if(!empty($error)):?><div class="alert alert-danger"><?=html_escape($error)?></div><?php endif;?>
 <form method="post" action="<?=base_url('cms/pages/save/'.($isEdit?$page->pageID:0))?>" class="mt-3">
  <div class="row"><div class="col-md-6 mb-3"><label class="form-label">Title</label><input class="form-control" name="pageTitle" required value="<?=html_escape($val('pageTitle'))?>"></div><div class="col-md-6 mb-3"><label class="form-label">URL</label><div class="input-group"><span class="input-group-text">/pages/</span><input class="form-control" name="pageSlug" required pattern="[A-Za-z0-9-]+" value="<?=html_escape($val('pageSlug'))?>" placeholder="aboutus"></div><small class="text-muted">Public URL: <?=html_escape(base_url('pages/'))?>your-slug</small></div></div>
  <div class="mb-3"><div class="d-flex justify-content-between align-items-center"><label class="form-label mb-1">Page Content</label><div class="btn-group btn-group-sm"><button type="button" class="btn btn-outline-primary active" id="visual-mode">HTML view</button><button type="button" class="btn btn-outline-primary" id="code-mode">Code view</button></div></div>
   <textarea class="form-control" id="pageContent" name="pageContent" rows="16" style="font-family:monospace"><?=html_escape($val('pageContent'))?></textarea><div id="visualEditor" contenteditable="true" class="form-control" style="display:none;min-height:320px;overflow:auto"></div><small class="text-muted">Switch between visual editing and HTML source. Use Code view for precise markup.</small></div>
  <div class="mb-3"><label class="form-label">Custom CSS</label><textarea class="form-control" name="pageCSS" rows="7" style="font-family:monospace"><?=html_escape($val('pageCSS'))?></textarea></div>
  <div class="mb-3"><label class="form-label">Custom JavaScript</label><textarea class="form-control" name="pageJS" rows="7" style="font-family:monospace"><?=html_escape($val('pageJS'))?></textarea></div>
  <div class="form-check mb-3"><input class="form-check-input" type="checkbox" id="pageStatus" name="pageStatus" value="1" <?=$val('pageStatus',1)?'checked':''?>><label class="form-check-label" for="pageStatus">Published</label></div>
  <button class="btn btn-primary" type="submit"><?=$isEdit?'Update Page':'Create Page'?></button>
 </form></div>
<script>
(function(){var src=document.getElementById('pageContent'),vis=document.getElementById('visualEditor'),v=document.getElementById('visual-mode'),c=document.getElementById('code-mode'),mode='code';function setMode(next){if(next===mode)return;if(next==='visual'){vis.innerHTML=src.value;src.style.display='none';vis.style.display='block';v.classList.add('active');c.classList.remove('active');}else{src.value=vis.innerHTML;vis.style.display='none';src.style.display='block';c.classList.add('active');v.classList.remove('active');}mode=next;}v.addEventListener('click',function(){setMode('visual')});c.addEventListener('click',function(){setMode('code')});src.form.addEventListener('submit',function(){if(mode==='visual')src.value=vis.innerHTML;});})();
</script>
